	// torse long (retour du 2026-10-10)
	const yEpaule = yCou - .035, yHanche = .68, yTaille = yHanche + .1, yGenou = .37, xJambe = .105;
	const pivots = { tete: [0, yCou, 0], torse: [0, yTaille, 0], bassin: [0, yHanche, 0] };

